CREATE FUNCTION public.em_enrollment_year_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.year_id<>OLD.year_id THEN RAISE EXCEPTION 'Utiliser le transfert annuel pour conserver l’inscription précédente'; END IF; RETURN NEW; END $$;
CREATE TRIGGER em_enrollment_year_guard BEFORE UPDATE ON public.em_enrollments FOR EACH ROW EXECUTE FUNCTION public.em_enrollment_year_guard();
REVOKE ALL ON FUNCTION public.em_enrollment_year_guard() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.em_transfer_year(_id uuid,_year uuid,_classe text,_admission date,_statut text,_notes text) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e public.em_enrollments; result uuid; BEGIN IF NOT public.em_principal() THEN RAISE EXCEPTION 'Accès interdit' USING ERRCODE='42501'; END IF; SELECT * INTO e FROM public.em_enrollments WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Inscription introuvable'; END IF; IF _year=e.year_id THEN RAISE EXCEPTION 'Choisir une autre année'; END IF; INSERT INTO public.em_enrollments(membre_id,year_id,classe,admission,statut,notes) VALUES(e.membre_id,_year,_classe,_admission,_statut,_notes) RETURNING id INTO result; INSERT INTO public.em_audit(entity,entity_id,acteur_id,action,avant,apres) VALUES('em_enrollments',_id,auth.uid(),'TRANSFER_YEAR',to_jsonb(e),jsonb_build_object('nouvelle_inscription',result,'year_id',_year,'classe',_classe)); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.em_transfer_year(uuid,uuid,text,date,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.em_transfer_year(uuid,uuid,text,date,text,text) TO authenticated,service_role;
CREATE FUNCTION public.em_submission_checks() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE i integer; BEGIN IF TG_OP='UPDATE' AND OLD.statut IN ('valide','reserve','rejete') AND NEW.statut NOT IN (OLD.statut,'brouillon') THEN RAISE EXCEPTION 'Réouvrir le rapport avant de changer la décision'; END IF; IF NEW.statut='soumis' AND (TG_OP='INSERT' OR OLD.statut<>'soumis') THEN IF length(trim(coalesce(NEW.contenu->>'attestant','')))=0 OR length(trim(coalesce(NEW.contenu->>'fonction','')))=0 OR coalesce(NEW.contenu->>'date_attestation','')='' THEN RAISE EXCEPTION 'Nom, fonction et date d’attestation obligatoires'; END IF; PERFORM (NEW.contenu->>'date_attestation')::date; IF NEW.type='garde' THEN PERFORM (NEW.contenu->>'date')::date; FOR i IN 0..5 LOOP IF coalesce(NEW.contenu->>('evaluation_'||i),'') NOT IN ('Très satisfaisant','Satisfaisant','À améliorer') THEN RAISE EXCEPTION 'Les six critères d’évaluation du responsable sont obligatoires'; END IF; END LOOP; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_em_submission_checks BEFORE INSERT OR UPDATE ON public.em_reports FOR EACH ROW EXECUTE FUNCTION public.em_submission_checks();
REVOKE ALL ON FUNCTION public.em_submission_checks() FROM PUBLIC,anon,authenticated;